WITH with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) AS prev_txn_time FROM transactions), with_gaps AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT id, txn_type, amount, merchant, is_flagged, prev_txn_time, session_id, CASE WHEN merchant RLIKE '^(Lazada|Amazon)$' THEN 'GROUP_A' ELSE 'EXTENDED' END AS merchant_zone FROM sessions_transactions ORDER BY id DESC
